// 由 scripts/gen-css.mjs 生成（`pnpm run gen:css`）：改样式请改那个 .css 文件后重新生成。
export const PICKER_CSS = "\n/* 控件占位宽度由根盒吃：width / minWidth / maxWidth 内联在 .dshpc-picker 上。\n   根盒是 inline-block，只给定内层触发器时 shrink-to-fit 会按选中文字的 max-content 撑宽根盒，\n   含百分比的 clamp 在固有尺寸阶段又解不出来 ⇒ 长模型名让控件右侧留白、同排控件被挤（2026-11-10 真机）。\n   根盒定宽后百分比相对父 flex 行解析，超长文字只由 __label 的省略号接住，控件不再跟着内容跳。 */\n.dshpc-picker{position:relative;display:inline-block;max-width:100%;min-width:0;font-size:13px;line-height:20px}\n/* cascade 外层行之前没有布局：两个 inline-block 按基线排 ⇒ 供应商框下沉、两框之间只剩 HTML 空白看着连体。\n   这里只给默认值，:where() 特异性 0，消费方 rowClassName 的任意规则都能盖回来。 */\n:where(.dshpc-picker__cascade){display:flex;align-items:center;gap:8px}\n/* 触发器铺满根盒；hint 态多一层 fieldwrap，那层也铺满、按钮吃剩余宽度给问号让位。\n   尺寸只由根盒持有：默认下限（PICKER_DEFAULT_MIN_WIDTH）与调用方三轴都在根盒的内联 style 里，\n   trigger 一条 min/max 都不能有 —— 否则 width:96 会被 trigger 的 120 下限顶到 120，\n   向右溢出盖住邻格（2026-11-11 用户截图：年份下拉溢出 24px 压到月份滑轨）。 */\n.dshpc-picker > .dshpc-picker__trigger{width:100%;box-sizing:border-box}\n.dshpc-picker > .dshpc-fieldwrap{display:flex;width:100%;box-sizing:border-box}\n.dshpc-picker .dshpc-fieldwrap > .dshpc-picker__trigger{flex:1 1 auto;width:auto;min-width:0}\n.dshpc-picker__trigger{\n  display:inline-flex;align-items:center;justify-content:space-between;gap:6px;\n  min-width:0;height:28px;padding:0 8px;\n  color:var(--dshpc-fg);background:var(--dshpc-surface-1);\n  border:1px solid var(--dshpc-border-heavy);border-radius:var(--dshpc-radius-md);cursor:pointer;\n}\n.dshpc-picker__trigger:disabled{color:var(--dshpc-fg-dim);cursor:not-allowed;opacity:.7}\n/* 聚焦（键盘或点击选中）时与全站一致的蓝色描边；菜单打开后焦点会进去，触发器自然失去焦点。 */\n.dshpc-picker__trigger:focus-visible{outline:2px solid var(--dshpc-focus);outline-offset:1px}\n/* 校验不通过：与 Input / Textarea 同口径，只描边框（2026-11-15）。hint 态下触发器在 fieldwrap 里，故不限定直接子级。 */\n.dshpc-picker--error .dshpc-picker__trigger{border-color:var(--dshpc-danger)}\n/* 文字默认靠左（吃掉剩余宽度），不给 space-between 把短文案推到中间的机会；\n   确实要居中就显式传 align=\"center\"。 */\n.dshpc-picker__label{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left}\n.dshpc-picker__trigger--center .dshpc-picker__label{text-align:center}\n.dshpc-picker__caret{flex:none;color:var(--dshpc-fg-3)}\n.dshpc-picker__icon{display:inline-flex;flex:none;color:var(--dshpc-fg-2)}\n.dshpc-picker__option-icon{display:inline-flex;flex:none;color:var(--dshpc-fg-2)}\n/* 下拉面板只留定位 / 裁切 / 字号：底色·描边·圆角·阴影来自 panel.css 的 menu 档。 */\n.dshpc-picker__menu{\n  z-index:var(--dshpc-z-popmenu);max-height:280px;overflow:hidden;\n  display:flex;flex-direction:column;\n  /* 菜单经 FloatingPortal 挂到 body，脱离 .dshpc-picker，须显式字号，否则继承 body 的大字号 */\n  font-size:13px;line-height:20px;\n}\n/* 固定头部（提示 + 搜索框），不随列表滚（2026-11-06 用户）。 */\n.dshpc-picker__head{flex:none;padding:4px 4px 0}\n/* 滚动在内层：列表贴满面板内容区，1px 让位由 .dshpc-scroll-thin 统一给\n   （不留缝就贴死在边框内壁上，2026-11-06 用户反馈）。上下角溢出由面板 overflow:hidden 裁掉。 */\n.dshpc-picker__list{flex:1 1 auto;min-height:0;overflow-y:auto;padding:0 4px 4px}\n/* 尺寸档（与 Field 的 sm/md/lg 对应）。 */\n.dshpc-picker__trigger--sm{height:24px;font-size:12px}\n.dshpc-picker__trigger--lg{height:32px}\n/* ── 菜单内部：全部收进 .dshpc-picker__menu 作用域（不要退回裸单类）─────────────\n   每个消费插件都把 core 内联进自己的产物，同一页上可能同时挂着**旧版 core** 的同一批\n   dshpc-* 规则（v0.35.15 的选项是 4px 圆角、提示条是通栏 0 圆角）。旧规则与本文件同为\n   单类选择器（0,1,0），谁后挂载谁赢 —— 2026-11-10 用户真机：选中行 / 悬停行 / 黄色提示块\n   三处圆角全退回旧值，而搜索框（旧版碰巧同值）看着正常。\n   收进菜单祖先（0,2,0）后，无论新旧 CSS 谁先注入，当前版本都赢。\n   根治是类名跨版本隔离（已知未完成项）；在那之前，这层作用域不是可选修饰。 */\n\n/* 键盘游标所在项（无 hover 也要看得见）。 */\n.dshpc-picker__menu .dshpc-picker__option[data-active='true']{background:var(--dshpc-surface-sunken);outline:1px solid var(--dshpc-border)}\n.dshpc-picker__menu .dshpc-picker__option--clear{color:var(--dshpc-fg-3)}\n.dshpc-picker__menu .dshpc-picker__search{\n  width:100%;height:28px;margin-bottom:4px;padding:0 8px;box-sizing:border-box;\n  color:var(--dshpc-fg);background:var(--dshpc-surface-sunken);\n  border:1px solid var(--dshpc-border-heavy);border-radius:var(--dshpc-radius-md);outline:none;\n}\n.dshpc-picker__menu .dshpc-picker__search::placeholder{color:var(--dshpc-fg-3)}\n.dshpc-picker__menu .dshpc-picker__group-label{\n  padding:6px 8px 2px;color:var(--dshpc-fg-3);font-size:11px;\n}\n/* 圆角只跟全站「框 / 行」那一档走：--dshpc-radius-md。\n   真源是 Surface（surface.css:4-5「容器档 = --dshpc-radius-md，与 Button / Input 同档」），ListRow 的行\n   圆角也是从 Surface 继承的 —— 所以这里不能自己挑 xs/sm 之类更小的档。2026-11-10 用户真机截图：\n   搜索框（md）与被选中的蓝行（xs）圆角明显不齐，同在一个面板里像两套控件。\n   大圆角仍然只归外层菜单（panel.css 的 menu 档 + overflow:hidden）。 */\n.dshpc-picker__menu .dshpc-picker__option{\n  display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:var(--dshpc-radius-md);cursor:pointer;\n  color:var(--dshpc-fg);white-space:nowrap;\n}\n/* 行与行之间隔 1px（用户 2026-11-10 指名：只要 1px，不要间距四拍里的 4px —— 四档是排版用的，\n   这种「把两条底色分开一点」的细分缝是用户点名的值，按原样写）。 */\n.dshpc-picker__menu .dshpc-picker__option + .dshpc-picker__option{margin-top:1px}\n/* hover / 选中直接借 ListRow 的两条 token —— 同一个「行」语义，与列表条目对齐。\n   选中不染文字色：蓝字是「链接」语义，行选中只换底（list-row.css:44-47 的口径）。\n   2026-11-10 用户：原来蓝底蓝字 + 亮一点的灰，和 ListRow 完全不是一套。 */\n.dshpc-picker__menu .dshpc-picker__option:hover{background:var(--dshpc-listrow-hover-bg)}\n.dshpc-picker__menu .dshpc-picker__option--active{background:var(--dshpc-listrow-selected-bg);color:var(--dshpc-fg)}\n.dshpc-picker__menu .dshpc-picker__option--disabled{color:var(--dshpc-fg-dim);cursor:not-allowed}\n/* 选项文字吃掉剩余宽度：超长省略号（配合 MarqueeText hover 跑马灯），不撑宽菜单。 */\n.dshpc-picker__menu .dshpc-picker__option-label{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dshpc-picker__menu .dshpc-picker__tick{width:12px;color:var(--dshpc-business)}\n.dshpc-picker__menu .dshpc-picker__empty{padding:8px;color:var(--dshpc-fg-3);text-align:center}\n/* 提示条（候选不完整 / 已到上限）与列表行同一套「块」：md 圆角 + 行内距，左右对齐搜索框与选项\n   （不再靠负 margin 伸到菜单内壁），只是配色换成提示黄。2026-11-10 用户：那条通栏太难看了，\n   要做成下面选中行那种框、用提示色。 */\n.dshpc-picker__menu .dshpc-picker__degraded{\n  padding:6px 8px;margin:0 0 4px;border-radius:var(--dshpc-radius-md);\n  color:var(--dshpc-warning-label);background:color-mix(in srgb,var(--dshpc-warning) 12%,transparent);\n  font-size:11px;\n}\n.dshpc-picker__menu .dshpc-picker__row{display:flex;align-items:center;gap:8px}\n/* 「显示更多」跟在最后一条后面、长得像多一条选项（2026-11-06 用户：翻到底发现不全才会找它）。\n   圆角同样走 md：它视觉上就是列表里多出来的一行，档位与选项一致，别再单独挑一个。 */\n.dshpc-picker__menu .dshpc-picker__more{\n  display:block;width:100%;margin-top:1px;padding:6px 8px;\n  color:var(--dshpc-business);background:none;\n  border:0;border-radius:var(--dshpc-radius-md);cursor:pointer;\n  font-size:12px;line-height:20px;text-align:center;\n}\n.dshpc-picker__menu .dshpc-picker__more:hover{background:var(--dshpc-surface-sunken)}\n"
